<?php
declare(strict_types=1); namespace App\Http\Controllers;
use App\Application\Services\CheckoutService; use Swoole\Http\Request;
final class CheckoutController extends Controller { public function __construct(private CheckoutService $checkout){} public function quote(Request $r,array $data):array{return $this->ok($this->checkout->quote($this->requireAuthUserId($r),$data));} public function order(Request $r,array $data):array{return $this->created($this->checkout->order($this->requireAuthUserId($r),$data,(string)($r->header['idempotency-key']??'')));} public function payment(Request $r,array $data):array{return $this->created($this->checkout->payment($this->requireAuthUserId($r),$data,(string)($r->header['idempotency-key']??'')));} public function verify(Request $r,string $attemptId):array{return $this->ok($this->checkout->verify($this->requireAuthUserId($r),$attemptId));} }
